class MyServlet extends HttpServlet {
    static final JAXBContext context = initContext();

    private static JAXBContext initContext() {
        return JAXBContext.newInstance(Foo.class,Bar.class);
    }
}

public void doGet( HttpServletRequest req, HttpServletResponse ) {
    Unmarshaller u = context.createUnmarshaller();
    u.unmarshal(...);
}

// Create once and share: a configured XMLInputFactory is thread safe.
static final XMLInputFactory XML_INPUT = createInputFactory();

private static XMLInputFactory createInputFactory() {
    XMLInputFactory factory = XMLInputFactory.newFactory();
    factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
    factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
    return factory;
}

Object read(Unmarshaller u, InputStream in) throws JAXBException, XMLStreamException {
    XMLStreamReader reader = XML_INPUT.createXMLStreamReader(in);
    try {
        return u.unmarshal(reader);
    } finally {
        reader.close();
    }
}
